const tsById = id => S.ts.find(t=>t.id===id);
const tail = s => (String(s||'').match(/\d{3}/)||[''])[0];
const tsByTail = t => S.ts.find(x=>tail(x.tyagach)===t);
function cls(code){
  if(!code) return '';
  const m={'в':'v','отп':'otp','бл':'bl','бс':'bs','П':'P','РП':'RP','Р':'R','РАН':'P','ПОЗ':'P'};
  if(m[code]) return m[code];
  return /^\d{3}$/.test(code)? 'zam' : '';
}
/* ТС, на котором водитель работает в этот день (или null) */
function worksOn(d, mk, day){
  const c = d.plan[mk][day];
  if(c==='в') return d.ts || null;
  if(/^\d{3}$/.test(c)){ const t=tsByTail(c); return t? t.id : '#'+c; }
  return null;
}
/* сколько дней подряд «в» к указанному дню (по сквозной ленте всех месяцев) */
function runLen(d, mk, day){
  const belt=[]; let idx=-1;
  MK.forEach(k=>{ if(k===mk) idx=belt.length+day; belt.push(...(d.plan[k]||[])); });
  let n=0;
  while(idx>=0 && (belt[idx]==='в' || /^\d{3}$/.test(belt[idx]||''))){ n++; idx--; }
  return n;
}
function rezLimit(r){ const m=/^(\d+)\//.exec(r||''); return m? +m[1] : 0; }
/* номер дня внутри непрерывной вахты — по сквозной ленте всех месяцев.
   День пересмены «П» считаем отработанным: человек в этот день ещё на машине. */
function vahtaDays(dr, lay){
  const belt=[], pos={};
  MK.forEach(k=>{ pos[k]=belt.length; belt.push(...((dr[lay]||{})[k]||[])); });
  const num=new Array(belt.length).fill(0); let c=0;
  belt.forEach((x,i)=>{
    const w = x==='в' || x==='П' || x==='РП' || /^\d{3}$/.test(x||'');
    if(w){ c++; num[i]=c; } else c=0;
  });
  return {num, pos, N:rezLimit(dr.rezhim)};
}
/* дни сверх вахты за показанный период */
function overInfo(dr, lay, days){
  const v=vahtaDays(dr,lay);
  const over={}; let n=0;
  if(v.N) days.forEach((r,i)=>{
    const k=v.num[v.pos[r.mk]+r.d];
    if(k>v.N){ over[i]=k-v.N; n++; }
  });
  return {over, n, N:v.N};
}

