/* продолжение вахты по режиму: N дней работы, последний из них — пересмена, затем R дней отдыха */
function extendCycle(d, slots){
  const m=/^(\d+)\s*\/\s*(\d+)$/.exec(d.rezhim||'');
  /* подменным без закреплённой машины цикл не достраиваем: они выходят замещением,
     и угадывать, на какую машину, нельзя */
  if(!m || d.vac || !d.ts) return false;
  const N=+m[1], R=+m[2];
  const belt=[]; MK.forEach(k=>belt.push(...(d.plan[k]||[])));
  let i=belt.length-1; while(i>=0 && !belt[i]) i--;       /* хвост незаполненных дней пропускаем */
  if(i<0) return false;
  const isWork=x=>x==='в'||/^\d{3}$/.test(x||'');
  let phase, cnt=0;
  if(belt[i]==='П'){ phase='rest'; cnt=0; }
  else if(isWork(belt[i])){ phase='work'; let k=i; while(k>=0 && isWork(belt[k])){ cnt++; k--; } }
  else if(belt[i]==='отп'){ phase='rest'; let k=i; while(k>=0 && belt[k]==='отп'){ cnt++; k--; } }
  else return false;                                      /* больничный, ремонт — цикл не достраиваем */
  slots.forEach(sl=>{
    let code;
    if(phase==='work'){ cnt++; code = cnt>=N? 'П':'в'; if(cnt>=N){ phase='rest'; cnt=0; } }
    else { cnt++; code='отп'; if(cnt>=R){ phase='work'; cnt=0; } }
    d.plan[sl.k][sl.i]=code;
  });
  return true;
}
function addMonth(auto){
  const key=nextKey(MK[MK.length-1]), M=monInfo(key);
  const tail=MK[MK.length-1];
  if(!confirm(auto
      ? `Добавить ${M.name} и продолжить вахты по режиму каждого водителя?\nНезаполненный хвост ${MON[tail].name} тоже будет достроен.`
      : `Добавить ${M.name} пустым?`)) return;
  S.months.push(key); rebuildMonths();
  S.drv.forEach(d=>{ d.plan[key]=Array(M.days).fill(''); d.fact[key]=Array(M.days).fill(''); });
  let n=0, skip={rez:0, ts:0, other:0};
  if(auto){
    S.drv.forEach(d=>{
      if(d.vac) return;
      const slots=[];
      const prev=d.plan[tail]||[];
      let last=prev.length-1; while(last>=0 && !prev[last]) last--;
      for(let i=last+1; i<prev.length; i++) slots.push({k:tail, i});
      for(let i=0; i<M.days; i++) slots.push({k:key, i});
      if(extendCycle(d, slots)) n++;
      else if(!/^\d+\s*\/\s*\d+$/.test(d.rezhim||'')) skip.rez++;
      else if(!d.ts) skip.ts++;
      else skip.other++;
    });
  }
  fillMonthSelects();
  document.getElementById('fMonth').value=key;
  logAdd(auto? `добавлен ${M.name}, вахты продолжены по режиму (${n} водителей)`
             : `добавлен ${M.name} (пустой)`, []);
  save(); redraw();
  document.getElementById('msg').innerHTML = auto
    ? `${M.name} добавлен: график продолжен по режиму для <b style="color:var(--ink)">${n}</b> водителей. `+
      `Пропущены: <b>${skip.rez}</b> без заданного режима (колонка «Режим» в строке водителя), `+
      `<b>${skip.ts}</b> подменных без закреплённой машины, <b>${skip.other}</b> закончили месяц больничным или ремонтом.`
    : `${M.name} добавлен пустым — заполняйте кистью или заливкой диапазоном.`;
}
document.getElementById('btnAddMonth').onclick=()=>addMonth(false);
document.getElementById('btnExtend').onclick=()=>addMonth(true);
document.getElementById('btnDelMonth').onclick=()=>{
  if(MK.length<2){ alert('Должен остаться хотя бы один месяц.'); return; }
  const key=MK[MK.length-1], M=MON[key];
  const filled=S.drv.reduce((a,d)=>a+(d.plan[key]||[]).filter(Boolean).length,0);
  if(!confirm(`Убрать ${M.name}? Заполненных клеток в нём: ${filled}. Данные месяца будут удалены.`)) return;
  S.months=S.months.filter(k=>k!==key); rebuildMonths();
  S.drv.forEach(d=>{ delete d.plan[key]; delete d.fact[key]; });
  fillMonthSelects();
  logAdd(`убран ${M.name}`, []);
  save(); redraw();
};

/* ---------- период и три плоскости ---------- */
function daysSel(){
  const v=document.getElementById('fMonth').value, out=[];
  const add=mk=>{ for(let d=0; d<MON[mk].days; d++)
    out.push({mk, d, n:d+1, short:MON[mk].short, mname:MON[mk].name,
              wd:new Date(MON[mk].y,MON[mk].m,d+1).getDay()}); };
  if(v==='both') MK.forEach(add); else if(MON[v]) add(v); else add(MK[MK.length-1]);
  return out;
}
function daysOf(mk){ const out=[]; for(let d=0; d<MON[mk].days; d++)
  out.push({mk, d, n:d+1, short:MON[mk].short, wd:new Date(MON[mk].y,MON[mk].m,d+1).getDay()}); return out; }
function periodName(){ const v=document.getElementById('fMonth').value;
  if(v!=='both') return MON[v]? MON[v].name : '';
  return MK.length>1? MON[MK[0]].name+' – '+MON[MK[MK.length-1]].name : MON[MK[0]].name; }
function dayLabel(r){ return r.n+' '+r.short; }
const cget=(dr,lay,r)=>(((dr[lay]||{})[r.mk])||[])[r.d]||'';
const cset=(dr,lay,r,c)=>{ if(!dr[lay]) dr[lay]={};
  if(!dr[lay][r.mk]) dr[lay][r.mk]=Array(MON[r.mk].days).fill('');
  dr[lay][r.mk][r.d]=c; };
const shortFio=f=>{ if(!f) return ''; const p=f.split(' ')[0];
  return p.slice(0,3); };   /* в клетке помещается 3 буквы, полное имя — в подсказке */

function rowsFor(){
  const f=document.getElementById('fFilial').value;
  const q=document.getElementById('fSearch').value.trim().toLowerCase();
  const onlyVac=document.getElementById('fVac').checked;
  return S.drv.filter(d=>{
    if(f!=='Все' && d.filial!==f) return false;
    if(onlyVac && !d.vac) return false;
    if(q){
      const t=tsById(d.ts);
      const hay=((d.fio||'')+' '+(t?t.tyagach:'')+' '+d.crew).toLowerCase();
      if(!hay.includes(q)) return false;
    }
    return true;
  });
}
/* плоскость 1 — машина: кто занимает сцепку в каждый день */
function occupant(dr,r){
  const c=cget(dr,'plan',r);
  if(c==='в') return dr.ts||null;
  if(/^\d{3}$/.test(c)){ const t=tsByTail(c); return t? t.id : null; }
  return null;
}
function occupancy(days,set){
  const occ={}; S.ts.forEach(t=>occ[t.id]=days.map(()=>null));
  set.forEach(dr=>days.forEach((r,i)=>{
    const id=occupant(dr,r); if(!id||!occ[id]) return;
    occ[id][i] = occ[id][i] ? {drv:occ[id][i].drv, second:dr, conflict:true} : {drv:dr};
  }));
  return occ;
}
/* плоскость 2 — водитель: сколько дней подряд в рейсе */
function runAt(dr,days,i){ let n=0,k=i;
  while(k>=0){ const c=cget(dr,'plan',days[k]); if(c==='в'||/^\d{3}$/.test(c)){ n++; k--; } else break; }
  return n; }
/* плоскость 3 — пересмена: где на машине сменился водитель и вовремя ли */
function handovers(days,occ){
  const list=[];
  Object.keys(occ).forEach(tid=>{
    let prev=null, prevIdx=-1;
    occ[tid].forEach((cell,i)=>{
      const cur = cell && cell.drv ? cell.drv : null;
      if(cur && prev && cur.id!==prev.id){
        const lim=rezLimit(prev.rezhim), run=runAt(prev,days,prevIdx);
        const markP=[i-1,i,i+1].some(k=>days[k] &&
          ['П','РП'].includes(cget(prev,'plan',days[k])) || days[k] && ['П','РП'].includes(cget(cur,'plan',days[k])));
        let status='вовремя', kind='ok';
        if(!markP){ status='пересмена не отмечена кодом П'; kind='bad'; }
        else if(lim && run>lim+3){ status='с опозданием на '+(run-lim)+' дн. (режим '+prev.rezhim+')'; kind='late'; }
        else if(lim && run<lim-3){ status='раньше срока на '+(lim-run)+' дн. (режим '+prev.rezhim+')'; kind='early'; }
        list.push({ts:tid, i, from:prev, to:cur, run, lim, status, kind});
      }
      if(cur){ prev=cur; prevIdx=i; }
    });
  });
  return list;
}
/* нарушения по строкам водителей */
function issues(days,set){
  const bad={};
  days.forEach((r,i)=>{
    const busy={};
    set.forEach((dr,ri)=>{
      if(cget(dr,'plan',r)==='в' && !dr.ts){ bad[ri+':'+i]='«в» без закреплённой машины'; return; }
      const id=occupant(dr,r); if(!id) return;
      if(busy[id]!==undefined){ bad[busy[id]+':'+i]='двое на одном ТС'; bad[ri+':'+i]='двое на одном ТС'; }
      else busy[id]=ri;
    });
  });
  set.forEach((dr,ri)=>{
    const lim=rezLimit(dr.rezhim); if(!lim) return;
    days.forEach((r,i)=>{
      const c=cget(dr,'plan',r);
      if((c==='в'||/^\d{3}$/.test(c)) && runAt(dr,days,i)>lim+3)
        bad[ri+':'+i]=bad[ri+':'+i]||('в рейсе дольше режима '+dr.rezhim);
    });
  });
  return bad;
}
function dayStats(days,set,filial,occ){
  const fleet=S.ts.filter(t=>!filial||filial==='Все'||t.filial===filial).map(t=>t.id);
  const O = occ || occupancy(days,set);
  return days.map((r,i)=>{
    let v=0,zam=0,otp=0,bl=0,per=0,rem=0;
    set.forEach(dr=>{
      const c=cget(dr,'plan',r);
      if(c==='в') v++;
      else if(/^\d{3}$/.test(c)) zam++;
      else if(c==='отп') otp++;
      else if(c==='бл'||c==='бс') bl++;
      else if(c==='П'||c==='РП') per++;
      else if(c==='Р') rem++;
    });
    const busy=fleet.filter(id=>O[id] && O[id][i]).length;
    return {v,zam,otp,bl,per,rem, fleet:fleet.length, busy, free:Math.max(fleet.length-busy,0)};
  });
}

/* ---------- отрисовка графика ---------- */
let selected=new Set(), view=[], DAYS=[];
const FIX=[['Филиал',66],['Тягач',88],['Прицеп',84],['Тип',52],['Экипаж',52],['Водитель / машина',196],
           ['Режим',56],['Подряд',52],['Сверх нормы',86],['Изменил',104],['',40]];
let LEFT=[]; { let l=0; FIX.forEach(f=>{LEFT.push(l); l+=f[1];}); }

function renderGrid(){
  DAYS=daysSel();
  const layer=document.getElementById('fLayer').value;
  const plane=document.getElementById('fView').value;      // all | ts | drv
  const fil=document.getElementById('fFilial').value;
  let set=rowsFor();
  const bad=issues(DAYS,set);
  if(document.getElementById('fConf').checked)
    set=set.filter((r,i)=>Object.keys(bad).some(k=>+k.split(':')[0]===i));
  view=set;
  const occ=occupancy(DAYS,S.drv);
  const hands=handovers(DAYS,occ);
  const st=dayStats(DAYS,set,fil,occ);

  const fleetIds=S.ts.filter(t=>fil==='Все'||t.filial===fil).map(t=>t.id);
  const handsView=hands.filter(h=>fleetIds.includes(h.ts));
  const md=st.reduce((a,x)=>a+x.busy,0), cap=fleetIds.length*DAYS.length;
  const late=handsView.filter(h=>h.kind==='late').length;
  const overTotal={days:0, men:0, noRez:0};
  set.forEach(d=>{ if(d.vac) return;
    if(!rezLimit(d.rezhim)){ overTotal.noRez++; return; }
    const o=overInfo(d,'plan',DAYS); if(o.n){ overTotal.days+=o.n; overTotal.men++; } });
  const noP=handsView.filter(h=>h.kind==='bad').length;
  const kp=[['Сцепок',fleetIds.length,''],['Водителей',set.filter(d=>!d.vac).length,''],
    ['Вакансий',set.filter(d=>d.vac).length, set.filter(d=>d.vac).length?'bad':''],
    ['Машинодни',md+' из '+cap,''],['Укомплектовано', cap?Math.round(md/cap*100)+'%':'—',''],
    ['Дней без водителя',st.reduce((a,x)=>a+x.free,0), st.some(x=>x.free)?'bad':''],
    ['Смен водителя на машинах',handsView.length,''],
    ['Дней сверх вахты (план)', overTotal.days, overTotal.days?'bad':''],
    ['Водителей с переработкой', overTotal.men, overTotal.men?'bad':''],
    ['С опозданием',late, late?'bad':''],
    ['Без отметки П',noP, noP?'bad':''],
    ['Нарушений',Object.keys(bad).length, Object.keys(bad).length?'bad':'']];
  document.getElementById('kpis').innerHTML=kp.map(([l,v,c])=>
    `<div class="kpi ${c}"><b>${v}</b><span>${l}</span></div>`).join('');

  /* шапка */
  const monthTh=[], dayTh=[], sums={'машин в работе':[],'без водителя':[],'пересмен':[],'отпуск':[]};
  let curM=null, span=0;
  DAYS.forEach((r,i)=>{
    if(r.mname!==curM){ if(curM) monthTh.push(`<th colspan="${span}">${curM}</th>`); curM=r.mname; span=0; }
    span++;
    const we=(r.wd===0||r.wd===6)?' we':'';
    const td=(r.mk===TODAY.mk && r.n===TODAY.d)?' today':'';
    dayTh.push(`<th class="${we}${td}">${r.n}</th>`);
    sums['машин в работе'].push(`<th class="${we}">${st[i].busy}</th>`);
    sums['без водителя'].push(`<th class="${we}" style="color:${st[i].free?'var(--warn)':'inherit'}">${st[i].free||''}</th>`);
    sums['пересмен'].push(`<th class="${we}">${st[i].per||''}</th>`);
    sums['отпуск'].push(`<th class="${we}">${st[i].otp}</th>`);
  });
  if(curM) monthTh.push(`<th colspan="${span}">${curM}</th>`);

  const fixTh=FIX.map((f,i)=>`<th class="fix" style="left:${LEFT[i]}px;min-width:${f[1]}px">${f[0]}</th>`).join('');
  const fixBlank=FIX.map((f,i)=>`<th class="fix" style="left:${LEFT[i]}px"></th>`).join('');
  let h=`<thead><tr>${fixBlank}${monthTh.join('')}</tr><tr>${fixTh}${dayTh.join('')}</tr>`;
  Object.entries(sums).forEach(([lbl,cells])=>{
    h+=`<tr class="sum">${FIX.map((f,i)=>`<th class="fix lbl" style="left:${LEFT[i]}px">${i===FIX.length-1?lbl:''}</th>`).join('')}${cells.join('')}</tr>`;
  });
  h+='</thead><tbody>';

  /* строки: по экипажам — сначала машины, затем водители */
  const byCrew=[]; const seenCrew={};
  set.forEach(dr=>{ if(!seenCrew[dr.crew]){ seenCrew[dr.crew]=[]; byCrew.push(dr.crew); } seenCrew[dr.crew].push(dr); });
  const handAt={}; hands.forEach(x=>handAt[x.ts+':'+x.i]=x);

  byCrew.forEach(cid=>{
    let first=true;
    if(plane!=='drv'){
      const onlyGap=document.getElementById('fGap').checked;
      S.ts.filter(t=>t.crew===cid && (fil==='Все'||t.filial===fil)).forEach(t=>{
        const line=occ[t.id], busy=line.filter(Boolean).length;
        if(onlyGap && busy===DAYS.length) return;
        const cells=line.map((c,i)=>{
          const r=DAYS[i], we=(r.wd===0||r.wd===6)?' we':'';
          const hv=handAt[t.id+':'+i];
          const hcls=hv? ' hand '+hv.kind : '';
          const title=hv? `пересмена ${dayLabel(r)}: ${hv.from.fio||'?'} → ${hv.to.fio||'?'}, ${hv.status}` : '';
          if(c && c.conflict) return `<td class="mday conflict${we}" title="двое: ${c.drv.fio} и ${c.second.fio}">!!</td>`;
          if(c) return `<td class="mday v${we}${hcls}" title="${(c.drv.fio||'подмена')}${title?' · '+title:''}">${shortFio(c.drv.fio)||'—'}</td>`;
          return `<td class="mday gap${we}" title="${dayLabel(r)}: машина без водителя"></td>`;
        }).join('');
        h+=`<tr class="${first?'crew-top':''} machine">`+
           `<td class="fix" style="left:${LEFT[0]}px">${t.filial}</td>`+
           `<td class="fix" style="left:${LEFT[1]}px"><b>${t.tyagach}</b></td>`+
           `<td class="fix" style="left:${LEFT[2]}px">${t.pricep}</td>`+
           `<td class="fix" style="left:${LEFT[3]}px">${t.tip}</td>`+
           `<td class="fix" style="left:${LEFT[4]}px">${t.crew}</td>`+
           `<td class="fix" style="left:${LEFT[5]}px">машина · закрыта ${busy} из ${DAYS.length} дн.
              <select class="inline" data-act="assign" data-ts="${t.id}">${drvOptions(t.id)}</select></td>`+
           `<td class="fix" style="left:${LEFT[6]}px"></td>`+
           `<td class="fix" style="left:${LEFT[7]}px"></td>`+
           `<td class="fix" style="left:${LEFT[8]}px"></td>`+
           `<td class="fix" style="left:${LEFT[9]}px"></td>`+
           `<td class="fix" style="left:${LEFT[10]}px">ТС</td>${cells}</tr>`;
        first=false;
      });
    }
    if(plane==='ts') return;
    seenCrew[cid].forEach(dr=>{
      const ri=set.indexOf(dr), t=tsById(dr.ts);
      const layers = layer==='both'? ['plan','fact'] : [layer];
      layers.forEach((lay,li)=>{
        const ov=overInfo(dr,lay,DAYS);
        const cells=DAYS.map((r,i)=>{
          const code=cget(dr,lay,r);
          const we=(r.wd===0||r.wd===6)?' we':'';
          const td=(r.mk===TODAY.mk && r.n===TODAY.d)?' today':'';
          const cf=(lay==='plan'&&bad[ri+':'+i])?' conflict':'';
          const ox=ov.over[i]? ' overday':'';
          const ttl= ov.over[i]
            ? ` title="${ov.over[i]}-й день сверх вахты ${dr.rezhim} — подлежит доплате"`
            : (bad[ri+':'+i]?` title="${bad[ri+':'+i]}"`:'');
          return `<td class="day ${cls(code)}${we}${td}${cf}${ox}" data-r="${ri}" data-i="${i}" data-l="${lay}" data-did="${dr.id}"${ttl}>${code}</td>`;
        }).join('');
        let info;
        if(li>0){
          info=FIX.map((f,i)=>`<td class="fix" style="left:${LEFT[i]}px">${i===FIX.length-1?'факт':''}</td>`).join('');
        }else{
          const run=runAt(dr,DAYS,DAYS.length-1), lim=rezLimit(dr.rezhim);
          const ovp=overInfo(dr,'plan',DAYS).n, ovf=overInfo(dr,'fact',DAYS).n;
          info=[
            `<td class="fix" style="left:${LEFT[0]}px"><select class="inline" data-act="filial" data-id="${dr.id}">
               ${['Пенза','Москва'].map(f=>`<option ${dr.filial===f?'selected':''}>${f}</option>`).join('')}</select></td>`,
            `<td class="fix" style="left:${LEFT[1]}px">${t?t.tyagach:'<span class="tag">подмена</span>'}</td>`,
            `<td class="fix" style="left:${LEFT[2]}px">${t?t.pricep:''}</td>`,
            `<td class="fix" style="left:${LEFT[3]}px">${t?t.tip:''}</td>`,
            `<td class="fix" style="left:${LEFT[4]}px">${dr.crew}</td>`,
            `<td class="fix" style="left:${LEFT[5]}px" title="${dr.tel||''}">
               <input type="checkbox" class="pick" data-r="${ri}" ${selected.has(dr.id)?'checked':''}>
               ${dr.vac? '<span class="vac">потребность</span> <button data-act="fillvac" data-id="'+dr.id+'" title="вписать водителя, сохранив расписанные дни">закрыть</button>' : dr.fio}</td>`,
            `<td class="fix" style="left:${LEFT[6]}px"><select class="inline" data-act="rez" data-id="${dr.id}">
               ${REZ.map(r=>`<option ${dr.rezhim===r?'selected':''}>${r||'—'}</option>`).join('')}</select></td>`,
            `<td class="fix ${lim&&run>lim?'over':''}" style="left:${LEFT[7]}px">${run||''}</td>`,
            `<td class="fix ${ovp||ovf?'over':''}" style="left:${LEFT[8]}px"
                 title="${lim? 'дней сверх вахты '+dr.rezhim+' за период: план '+ovp+', факт '+ovf : 'режим не задан — переработка не считается'}">
               ${lim? (ovp||ovf? ovp+' / '+ovf : '') : '<span class="who">режим?</span>'}</td>`,
            `<td class="fix" style="left:${LEFT[9]}px" title="${dr.lastBy?dr.lastBy+', '+fullTime(dr.lastAt):'правок не было'}">
               ${dr.lastBy? `${dr.lastBy} <span class="who">${shortTime(dr.lastAt)}</span>`:''}</td>`,
            `<td class="fix" style="left:${LEFT[10]}px">${layer==='both'?'план':(lay==='fact'?'факт':'план')}</td>`
          ].join('');
        }
        h+=`<tr class="${first&&li===0?'crew-top':''} ${lay==='fact'?'fact':''}">${info}${cells}</tr>`;
        if(li===0) first=false;
      });
    });
  });
  h+='</tbody>';
  document.getElementById('grid').innerHTML=h;
  document.getElementById('selInfo').textContent='строк выбрано: '+selected.size;

  const nb=Object.keys(bad).length;
  const parts=[];
  if(nb) parts.push(`<b>${nb}</b> дней с нарушениями в строках водителей`);
  if(late) parts.push(`<b>${late}</b> пересмен с опозданием`);
  if(overTotal.days) parts.push(`<b>${overTotal.days}</b> дней сверх вахты у ${overTotal.men} водителей — к доплате`);
  if(overTotal.noRez) parts.push(`у <b>${overTotal.noRez}</b> водителей не задан режим, переработка по ним не считается`);
  if(noP) parts.push(`<b>${noP}</b> пересмен без кода П`);
  document.getElementById('msg').innerHTML = parts.length
    ? parts.join(' · ')+'. Наведите на ячейку — покажет причину.'
    : 'Машины укомплектованы, пересмены в срок, нарушений нет.';
  document.getElementById('dFrom').max=DAYS.length; document.getElementById('dTo').max=DAYS.length;
  if(typeof paintSel==='function') paintSel();
}

/* ---------- ввод: выделение как в Excel, затем клик по коду ---------- */
let painting=false, strokes={};
let sel=new Set(), anchorKey=null;
const grid=document.getElementById('grid');
const keyOf=td=>{ const D=DAYS[+td.dataset.i];
  return td.dataset.did+'|'+td.dataset.l+'|'+D.mk+'|'+D.d; };
const tdByKey=k=>[...grid.querySelectorAll('td.day')].find(t=>keyOf(t)===k);
function paintSel(){
  grid.querySelectorAll('td.day.sel').forEach(t=>t.classList.remove('sel'));
  if(sel.size) grid.querySelectorAll('td.day').forEach(t=>{ if(sel.has(keyOf(t))) t.classList.add('sel'); });
  const box=document.getElementById('selInfo');
  if(box) box.textContent='строк выбрано: '+selected.size+(sel.size?` · дней выделено: ${sel.size}`:'');
}
function rectSelect(a,b,add){
  const r1=a.parentElement.rowIndex, r2=b.parentElement.rowIndex;
  const i1=+a.dataset.i, i2=+b.dataset.i;
  const rlo=Math.min(r1,r2), rhi=Math.max(r1,r2), ilo=Math.min(i1,i2), ihi=Math.max(i1,i2);
  if(!add) sel.clear();
  grid.querySelectorAll('td.day').forEach(t=>{
    const rr=t.parentElement.rowIndex, ii=+t.dataset.i;
    if(rr>=rlo&&rr<=rhi&&ii>=ilo&&ii<=ihi) sel.add(keyOf(t));
  });
  paintSel();
}
grid.addEventListener('mousedown',e=>{
  const td=e.target.closest('td.day'); if(!td) return;
  e.preventDefault();
  const a=anchorKey&&tdByKey(anchorKey);
  if(e.shiftKey&&a){ rectSelect(a,td,false); return; }
  if(e.ctrlKey||e.metaKey){ // добавить/убрать ячейку из выделения
    const k=keyOf(td);
    sel.has(k)? sel.delete(k) : sel.add(k);
    anchorKey=k; paintSel(); return;
  }
  anchorKey=keyOf(td); painting=true; rectSelect(td,td,false);
});
grid.addEventListener('mouseover',e=>{
  if(!painting) return;
  const td=e.target.closest('td.day'); const a=anchorKey&&tdByKey(anchorKey);
  if(td&&a) rectSelect(a,td,false);
});
document.addEventListener('mouseup',()=>{ painting=false; });
document.addEventListener('keydown',e=>{
  if(e.key==='Escape'&&!['INPUT','SELECT','TEXTAREA'].includes(document.activeElement?.tagName)){
    sel.clear(); paintSel();
  }
});
function applyCode(codeRaw){
  const code=codeFor(codeRaw); if(code===null) return;
  strokes={};
  if(sel.size){
    sel.forEach(k=>{
      const [did,l,mk,d]=k.split('|');
      const dr=S.drv.find(x=>x.id===did); if(!dr) return;
      const day={mk, d:+d};
      const idx=DAYS.findIndex(x=>x.mk===mk&&x.d===+d);
      if(cget(dr,l,day)!==code){
        if(!strokes[did]) strokes[did]={code, days:[]};
        if(idx>=0 && !strokes[did].days.includes(idx)) strokes[did].days.push(idx);
      }
      cset(dr,l,day,code);
    });
  } else if(selected.size){
    // выделения нет — работает прежняя массовая заливка: галки строк + «с/по»
    let a=+document.getElementById('dFrom').value||1, b=+document.getElementById('dTo').value||DAYS.length;
    if(a>b) [a,b]=[b,a];
    a=Math.max(1,a); b=Math.min(DAYS.length,b);
    const lay=document.getElementById('fLayer').value==='fact'? 'fact':'plan';
    S.drv.filter(d=>selected.has(d.id)).forEach(d=>{
      for(let i=a-1;i<b;i++){
        if(cget(d,lay,DAYS[i])!==code){
          if(!strokes[d.id]) strokes[d.id]={code, days:[]};
          if(!strokes[d.id].days.includes(i)) strokes[d.id].days.push(i);
        }
        cset(d,lay,DAYS[i],code);
      }
    });
  } else {
    document.getElementById('msg').innerHTML='<b>Сначала выделите дни</b> в сетке (клик, протяжка или Shift-клик), затем кликните код. Либо отметьте строки галочками и задайте диапазон «с/по».';
    return;
  }
  const ids=Object.keys(strokes);
  if(ids.length){
    const parts=ids.map(id=>{ const d=strokes[id].days.slice().sort((x,y)=>x-y);
      return d.length>1? dayLabel(DAYS[d[0]])+'–'+dayLabel(DAYS[d[d.length-1]]) : dayLabel(DAYS[d[0]]); });
    logAdd(`код «${code||'пусто'}», ${parts.join(', ')}`, ids);
  }
  save(); renderGrid();
}
grid.addEventListener('click',e=>{
  const b=e.target.closest('button[data-act="fillvac"]');
  if(b){ e.preventDefault(); fillVacancy(b.dataset.id); }
});
grid.addEventListener('change',e=>{
  const s=e.target.closest('select.inline');
  if(s && s.dataset.act==='assign'){
    if(s.value) assignDriver(s.value, s.dataset.ts);
    else renderGrid();
    return;
  }
  if(s){
    const d=S.drv.find(x=>x.id===s.dataset.id);
    if(s.dataset.act==='filial'){
      d.filial=s.value;
      if(d.ts){ const t=tsById(d.ts); t.filial=s.value;
                S.drv.filter(x=>x.ts===d.ts).forEach(x=>x.filial=s.value); }
      logAdd('филиал изменён на '+s.value, [d.id]);
    } else { d.rezhim = s.value==='—'? '' : s.value;
      logAdd('режим работы: '+(d.rezhim||'не задан'), [d.id]); }
    save(); renderGrid(); return;
  }
  const p=e.target.closest('input.pick');
  if(p){ const dr=view[+p.dataset.r];
    p.checked? selected.add(dr.id) : selected.delete(dr.id);
    paintSel(); }
});
function codeFor(codeRaw){
  if(codeRaw!=='ЗАМ') return codeRaw;
  const id=document.getElementById('zamTs').value;
  if(!id){ document.getElementById('msg').innerHTML='<b>Выберите тягач замещения</b> в списке рядом с кодами.'; return null; }
  return tail(tsById(id).tyagach);
}
// paint() упразднена: применение кодов — applyCode() по выделению.
// Массовая заливка «галки + с/по» делается кликом по коду (applyCode).
document.getElementById('btnFact').onclick=()=>{
  const v=document.getElementById('fMonth').value;
  const targets = selected.size? S.drv.filter(d=>selected.has(d.id)) : rowsFor();
  if(!confirm(`Переписать факт по плану за ${periodName()} для ${targets.length} строк?`)) return;
  const mks = v==='both'? MK.slice() : [v];
  targets.forEach(d=>mks.forEach(mk=>{ d.fact[mk]=d.plan[mk].slice(); }));
  logAdd(`${periodName()}: факт переписан по плану (${targets.length} строк)`, targets.map(d=>d.id));
  save(); renderGrid();
};


/* ---------- вкладка «Закрепление» ---------- */
function renderFix(){
  const f=document.getElementById('xFilial').value;
  const q=document.getElementById('xSearch').value.trim().toLowerCase();
  const onlyFree=document.getElementById('xFree').checked;
  const list=S.ts.filter(t=>{
    if(f!=='Все' && t.filial!==f) return false;
    const crew=S.drv.filter(d=>d.ts===t.id && !d.vac);
    if(onlyFree && crew.length) return false;
    if(q){
      const hay=(t.tyagach+' '+t.pricep+' '+t.crew+' '+crew.map(d=>d.fio).join(' ')).toLowerCase();
      if(!hay.includes(q)) return false;
    }
    return true;
  });
  const free=S.drv.filter(d=>!d.ts && !d.vac);
  let h=`<thead><tr><th>Тягач</th><th>Прицеп</th><th>Тип</th><th>Филиал</th><th>Экипаж</th>
         <th>Закреплённые водители</th><th>Добавить водителя</th><th></th></tr></thead><tbody>`;
  list.forEach(t=>{
    const crew=S.drv.filter(d=>d.ts===t.id);
    h+=`<tr>
      <td>${t.tyagach}</td><td>${t.pricep}</td><td>${t.tip}</td>
      <td><select class="inline" data-x="tsfil" data-id="${t.id}">
          ${['Пенза','Москва'].map(x=>`<option ${t.filial===x?'selected':''}>${x}</option>`).join('')}</select></td>
      <td>${t.crew}</td>
      <td>${crew.length? crew.map(d=>`${d.vac
            ? '<span class="vac">потребность</span> <button data-x="fillvac" data-id="'+d.id+'" title="вписать водителя">закрыть</button>'
            : d.fio}
            <button data-x="unpin" data-id="${d.id}" title="снять закрепление">×</button>`).join(' · ')
          : '<span class="vac">нет водителя</span>'}</td>
      <td><select class="inline" data-x="pin" data-id="${t.id}">${drvOptions(t.id)}</select></td>
      <td><button data-x="delts" data-id="${t.id}" title="удалить сцепку">удалить</button></td></tr>`;
  });
  h+='</tbody>';
  document.getElementById('fixTable').innerHTML=h;
  const noDrv=S.ts.filter(t=>!S.drv.some(d=>d.ts===t.id && !d.vac)).length;
  document.getElementById('fixMsg').innerHTML=
    `Сцепок: <b style="color:var(--ink)">${S.ts.length}</b> · без закреплённого водителя: <b>${noDrv}</b> · водителей без машины: <b style="color:var(--ink)">${free.length}</b>`;
}
document.getElementById('fixTable').addEventListener('change',e=>{
  const s=e.target.closest('select'); if(!s) return;
  if(s.dataset.x==='tsfil'){
    const t=tsById(s.dataset.id); t.filial=s.value;
    S.drv.filter(d=>d.ts===t.id).forEach(d=>d.filial=s.value);
    logAdd(t.tyagach+' переведён в филиал '+s.value, S.drv.filter(d=>d.ts===t.id).map(d=>d.id));
  }
  if(s.dataset.x==='pin' && s.value){ assignDriver(s.value, s.dataset.id); return; }
  save(); renderFix(); renderGrid(); fillZam();
});
document.getElementById('fixTable').addEventListener('click',e=>{
  const b=e.target.closest('button'); if(!b) return;
  if(b.dataset.x==='fillvac'){ fillVacancy(b.dataset.id); return; }
  if(b.dataset.x==='unpin'){ const d=S.drv.find(x=>x.id===b.dataset.id);
    const t=tsById(d.ts); d.ts=''; logAdd('снят с '+(t?t.tyagach:'машины'), [d.id]); }
  if(b.dataset.x==='delts'){
    if(!confirm('Удалить сцепку из поля?')) return;
    const t=tsById(b.dataset.id);
    S.drv.filter(d=>d.ts===b.dataset.id).forEach(d=>d.ts='');
    S.ts=S.ts.filter(x=>x.id!==b.dataset.id);
    logAdd('сцепка '+(t?t.tyagach:'')+' удалена из поля', []);
  }
  save(); renderFix(); renderGrid(); fillZam();
});
document.getElementById('btnAddTs').onclick=()=>{
  const ty=prompt('Гос. номер тягача'); if(!ty) return;
  const pr=prompt('Прицеп')||'', tp=prompt('Тип кузова')||'';
  const fl=prompt('Филиал: Пенза или Москва','Пенза')==='Москва'?'Москва':'Пенза';
  S.ts.push({id:'T'+Date.now(), tyagach:ty, pricep:pr, tip:tp, filial:fl, crew:'X'+Date.now()});
  logAdd('добавлена сцепка '+ty+' ('+fl+')', []);
  save(); renderFix(); fillZam();
};
document.getElementById('btnAddDrv').onclick=()=>{
  const fio=prompt('ФИО водителя'); if(!fio) return;
  const tel=prompt('Телефон')||'';
  const fl=prompt('Филиал: Пенза или Москва','Пенза')==='Москва'?'Москва':'Пенза';
  const nid='D'+Date.now();
  S.drv.push({id:nid, fio, tel, crew:'X'+Date.now(), filial:fl, ts:'', rezhim:'', logist:'', vac:false,
    plan:{aug:Array(31).fill(''), sep:Array(30).fill('')},
    fact:{aug:Array(31).fill(''), sep:Array(30).fill('')}});
  logAdd('добавлен водитель '+fio+' ('+fl+')', [nid]);
  save(); renderFix(); renderGrid();
};

/* ---------- сводка ---------- */
function renderSum(){
  const mk=document.getElementById('sMonth').value, M=MON[mk];
  const cards=[];
  ['Пенза','Москва','Все'].forEach(f=>{
    const set=S.drv.filter(d=>f==='Все'||d.filial===f);
    const st=dayStats(daysOf(mk),set,f);
    const fleet=S.ts.filter(t=>f==='Все'||t.filial===f).length;
    const md=st.reduce((a,x)=>a+x.busy,0), cap=fleet*M.days;
    cards.push(`<div class="card"><h3>${f==='Все'?'Оба филиала':'Филиал '+f}</h3><table>
      <tr><td>Сцепок</td><td>${fleet}</td></tr>
      <tr><td>Водителей</td><td>${set.filter(d=>!d.vac).length}</td></tr>
      <tr><td>Вакансий</td><td>${set.filter(d=>d.vac).length}</td></tr>
      <tr><td>Машинодни план</td><td>${md} / ${cap}</td></tr>
      <tr><td>Покрытие</td><td>${cap?Math.round(md/cap*100):0}%</td></tr>
      <tr><td>Отпуск, чел.-дней</td><td>${st.reduce((a,x)=>a+x.otp,0)}</td></tr>
      <tr><td>Пересмен</td><td>${st.reduce((a,x)=>a+x.per,0)}</td></tr>
      <tr><td>Дней без водителя</td><td>${st.reduce((a,x)=>a+x.free,0)}</td></tr></table></div>`);
  });
  document.getElementById('sumCards').innerHTML=cards.join('');
  const st=dayStats(daysOf(mk),S.drv,'Все');
  const max=Math.max(...st.map(x=>x.fleet),1);
  document.getElementById('sumBars').innerHTML=st.map((x,i)=>
    `<div title="${i+1}: в работе ${x.v+x.zam}, без водителя ${x.free}" style="height:${(x.v+x.zam)/max*100}%"></div>`+
    `<div class="b-free" title="${i+1}: без водителя ${x.free}" style="height:${x.free/max*100}%"></div>`).join('');
  let h=`<thead><tr><th>День</th><th>В работе</th><th>Замещений</th><th>Отпуск</th><th>Больн.</th>
         <th>Пересмен</th><th>Ремонт</th><th>ТС без водителя</th></tr></thead><tbody>`;
  st.forEach((x,i)=>{ h+=`<tr><td style="text-align:center">${i+1}</td><td style="text-align:center">${x.v+x.zam}</td>
    <td style="text-align:center">${x.zam}</td><td style="text-align:center">${x.otp}</td>
    <td style="text-align:center">${x.bl}</td><td style="text-align:center">${x.per}</td>
    <td style="text-align:center">${x.rem}</td>
    <td style="text-align:center;color:${x.free?'var(--warn)':'inherit'}">${x.free}</td></tr>`; });
  document.getElementById('sumTable').innerHTML=h+'</tbody>';
  renderOver(mk);
}
/* дни сверх вахты по каждому водителю — основание для доплаты */
function overRows(mk){
  const days=daysOf(mk), rows=[];
  S.drv.forEach(d=>{
    if(d.vac) return;
    const N=rezLimit(d.rezhim); if(!N) return;
    const p=overInfo(d,'plan',days), f=overInfo(d,'fact',days);
    if(!p.n && !f.n) return;
    const t=tsById(d.ts);
    rows.push({fio:d.fio, fil:d.filial, rez:d.rezhim, ts:t?t.tyagach:'', crew:d.crew,
               plan:p.n, fact:f.n, max:Math.max(...Object.values(p.over).concat([0]))});
  });
  return rows.sort((a,b)=>b.plan-a.plan || b.fact-a.fact);
}
function renderOver(mk){
  const rows=overRows(mk);
  let h=`<thead><tr><th>Водитель</th><th>Филиал</th><th>Экипаж</th><th>Тягач</th><th>Режим</th>
         <th>Сверх вахты, план</th><th>Сверх вахты, факт</th><th>Максимум переработки</th></tr></thead><tbody>`;
  rows.forEach(r=>{ h+=`<tr><td>${r.fio}</td><td>${r.fil}</td><td>${r.crew}</td><td>${r.ts}</td><td>${r.rez}</td>
    <td style="text-align:center;color:var(--warn);font-weight:700">${r.plan||''}</td>
    <td style="text-align:center">${r.fact||''}</td>
    <td style="text-align:center">${r.max? '+'+r.max+' дн.':''}</td></tr>`; });
  if(!rows.length) h+=`<tr><td colspan="8">За ${MON[mk].name} переработок по плану нет — либо не задан режим работы.</td></tr>`;
  document.getElementById('overTable').innerHTML=h+'</tbody>';
}
document.getElementById('btnOverCsv').onclick=()=>{
  const mk=document.getElementById('sMonth').value;
  const out=[['Месяц','Водитель','Филиал','Экипаж','Тягач','Режим','Сверх вахты план','Сверх вахты факт']];
  overRows(mk).forEach(r=>out.push([MON[mk].name, r.fio, r.fil, r.crew, r.ts, r.rez, r.plan, r.fact]));
  dl('sverh_vahty_'+mk+'.csv','text/csv',
     '\ufeff'+out.map(x=>x.map(v=>`"${String(v??'').replace(/"/g,'""')}"`).join(';')).join('\n'));
};

/* ---------- журнал ---------- */
function renderLog(){
  const who=document.getElementById('lWho'), q=document.getElementById('lSearch').value.trim().toLowerCase();
  const authors=[...new Set(S.log.map(e=>e.a))].sort();
  const cur=who.value||'Все';
  who.innerHTML=['Все',...authors].map(a=>`<option ${a===cur?'selected':''}>${a}</option>`).join('');
  const list=S.log.filter(e=>{
    if(cur!=='Все' && e.a!==cur) return false;
    if(q && !((e.what+' '+(e.who||'')).toLowerCase().includes(q))) return false;
    return true;
  });
  let h='<thead><tr><th style="min-width:120px">Когда</th><th style="min-width:110px">Кто</th>'+
        '<th style="min-width:220px">Кого касается</th><th>Что изменено</th></tr></thead><tbody>';
  list.slice(0,400).forEach(e=>{
    h+=`<tr class="${e.a===AUTHOR?'mine':''}"><td>${fullTime(e.t)}</td><td>${e.a}</td>
        <td>${e.who||'—'}</td><td>${e.what}</td></tr>`;
  });
  document.getElementById('logTable').innerHTML=h+'</tbody>';
  document.getElementById('logInfo').textContent=
    `записей: ${list.length}${S.log.length>list.length?' из '+S.log.length:''}${list.length>400?', показаны последние 400':''}`;
}
document.getElementById('btnLogCsv').onclick=()=>{
  const out=[['Когда','Кто','Кого касается','Что изменено']];
  S.log.forEach(e=>out.push([fullTime(e.t), e.a, e.who||'', e.what]));
  dl('zhurnal_pravok.csv','text/csv',
     '\ufeff'+out.map(r=>r.map(v=>`"${String(v??'').replace(/"/g,'""')}"`).join(';')).join('\n'));
};
['lWho','lSearch'].forEach(id=>document.getElementById(id).addEventListener('input',renderLog));

/* ---------- сервис ---------- */
document.getElementById('btnCsv').onclick=()=>{
  const days=daysSel();
  const head=['Филиал','Тягач','Прицеп','Тип','Экипаж','Водитель','Телефон','Режим','Слой']
    .concat(days.map(r=>dayLabel(r)));
  const out=[head];
  const occ=occupancy(days,S.drv);
  S.ts.forEach(t=>out.push([t.filial,t.tyagach,t.pricep,t.tip,t.crew,'машина','','','кто за рулём']
    .concat(occ[t.id].map(c=>c? (c.conflict?'двое!':(c.drv.fio||'подмена')) : 'нет водителя'))));
  rowsFor().forEach(d=>{
    const t=tsById(d.ts);
    ['plan','fact'].forEach(l=>out.push([d.filial,t?t.tyagach:'',t?t.pricep:'',t?t.tip:'',d.crew,
      d.vac?'потребность':d.fio, d.tel, d.rezhim, l==='plan'?'план':'факт']
      .concat(days.map(r=>cget(d,l,r)))));
  });
  dl('grafik_'+document.getElementById('fMonth').value+'_2026.csv','text/csv',
     '\ufeff'+out.map(r=>r.map(v=>`"${String(v??'').replace(/"/g,'""')}"`).join(';')).join('\n'));
};
document.getElementById('btnBackup').onclick=()=>dl('grafik_backup.json','application/json',JSON.stringify(S));
document.getElementById('btnRestore').onclick=()=>document.getElementById('fileIn').click();
document.getElementById('fileIn').onchange=e=>{
  const f=e.target.files[0]; if(!f) return;
  const rd=new FileReader();
  rd.onload=()=>{ try{ const o=JSON.parse(rd.result);
      if(!o.ts||!o.drv) throw 0; S=migrate(o); rebuildMonths();
      logAdd('загружена копия графика из файла', []); save(); redraw();
    }catch(err){ alert('Файл не похож на копию графика.'); } };
  rd.readAsText(f);
};
document.getElementById('btnReset').onclick=()=>{
  if(confirm('Вернуть август–сентябрь 2026 из исходного файла? Все правки будут потеряны.')){
    S=seed(); selected.clear(); logAdd('данные возвращены к исходному файлу', []); save(); redraw();
  }
};
function dl(name,type,data){
  const a=document.createElement('a');
  a.href=URL.createObjectURL(new Blob([data],{type})); a.download=name; a.click();
}
document.getElementById('btnHelp').onclick=()=>document.getElementById('help').hidden=false;
document.getElementById('btnHelpClose').onclick=()=>document.getElementById('help').hidden=true;
document.getElementById('help').onclick=e=>{ if(e.target.id==='help') e.target.hidden=true; };
document.addEventListener('keydown',e=>{ if(e.key==='Escape') document.getElementById('help').hidden=true; });
document.querySelectorAll('.tab').forEach(t=>t.onclick=()=>{
  document.querySelectorAll('.tab').forEach(x=>x.setAttribute('aria-selected', x===t));
  document.querySelectorAll('.pane').forEach(p=>p.classList.toggle('on', p.id==='pane-'+t.dataset.pane));
  if(t.dataset.pane==='fix') renderFix();
  if(t.dataset.pane==='sum') renderSum();
  if(t.dataset.pane==='log') renderLog();
});
['fFilial','fMonth','fLayer','fView','fSearch','fVac','fGap','fConf'].forEach(id=>
  document.getElementById(id).addEventListener('input',renderGrid));
['xFilial','xSearch','xFree'].forEach(id=>
  document.getElementById(id).addEventListener('input',renderFix));
document.getElementById('sMonth').addEventListener('input',renderSum);
function redraw(){ rebuildMonths(); fillMonthSelects(); fillZam(); renderGrid(); renderFix(); renderSum(); renderLog(); }
redraw();
startSync();
